package org.mockito.internal.creation.bytebuddy;

import java.io.*;
import java.lang.reflect.Constructor;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.exceptions.bytecode.MockitoException;
import org.mockito.internal.InternalMockHandler;
import org.mockito.internal.configuration.GlobalConfiguration;
import org.mockito.internal.creation.MockHandler;
import org.mockito.internal.creation.instance.*;
import org.mockito.internal.creation.instantiation.ClassInstantiator;
import org.mockito.internal.proxy.interceptors.MockMethodInterceptor;
import org.mockito.invocation.MockHandler;
import org.mockito.mock.MockCreationSettings;
import org.mockito.mock.SerializableMode;
import org.mockito.plugins.MockMaker;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import static org.mockito.internal.creation.bytebuddy.MockCreationSettings.MockCreationSettings;
import static org.mockito.internal.creation.bytebuddy.MockCreationSettings.SerializableMode;

public class ByteBuddyMockMaker_createMock_TriageGen0Test {

    private ByteBuddyMockMaker mockMaker;
    private MockCreationSettings<Object> settings;
    private MockHandler handler;
    private BytecodeGenerator cachingMockBytecodeGenerator;
    private ClassInstantiator classInstantiator;

    // Interface to allow mocking of the internal BytecodeGenerator which is usually a field
    public interface BytecodeGenerator {
        <T> Class<? extends T> get(Class<? extends T> type, Class<?>... extraInterfaces);
    }

    // Interface to allow mocking of the internal ClassInstantiator
    public interface ClassInstantiatorMock {
        <T> T instantiate(Class<? extends T> type) throws org.mockito.internal.creation.instance.InstantiationException;
    }

    // Mock access interface to simulate the cast in the method
    public interface MockAccess extends MockMethodInterceptor.MockAccess {}

    @Before
    public void setUp() throws Exception {
        mockMaker = new ByteBuddyMockMaker();
        settings = mock(MockCreationSettings.class);
        handler = mock(MockHandler.class);

        // Using reflection to inject mocks into the private fields of ByteBuddyMockMaker
        // since they are not provided via constructor in the snippet.
        cachingMockBytecodeGenerator = mock(BytecodeGenerator.class);
        classInstantiator = mock(ClassInstantiatorMock.class);

        setField(mockMaker, "cachingMockBytecodeGenerator", cachingMockBytecodeGenerator);
        setField(mockMaker, "classInstantiator", classInstantiator);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testCreateMock_ThrowsException_WhenSerializableModeIsAcrossClassloaders() {
        when(settings.getSerializableMode()).thenReturn(SerializableMode.ACROSS_CLASSLOADERS);

        try {
            mockMaker.createMock(settings, handler);
        } catch (MockitoException e) {
            assert(e.getMessage().contains("Serialization across classloaders not yet supported"));
            return;
        }
        throw new AssertionError("Expected MockitoException");
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testCreateMock_Success() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<MockAccess> proxyType = (Class<MockAccess>) MockAccess.class;
        MockAccess mockInstance = mock(MockAccess.class);

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(typeToMock, (Class[]) null)).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenReturn(mockInstance);

        // We need to mock ensureMockIsAssignableToMockedType behavior. 
        // Since it's a private method in the real class, we assume it returns the instance if valid.
        // However, since we can't easily mock private methods of the class under test without PowerMock,
        // and the method is part of the logic, this test assumes the real logic runs.
        // For the sake of this unit test, we assume the instance is returned.

        Object result = mockMaker.createMock(settings, handler);

        assert(result == mockInstance);
        verify(mockInstance).setMockitoInterceptor(any(MockMethodInterceptor.class));
    }

    @Test(expected = MockitoException.class)
    @SuppressWarnings("unchecked")
    public void testCreateMock_ThrowsException_WhenClassCastExceptionOccurs() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<Object> proxyType = Object.class; 
        Object nonMockInstance = new Object(); // This will cause ClassCastException when cast to MockAccess

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(typeToMock, (Class[]) null)).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenReturn(nonMockInstance);

        mockMaker.createMock(settings, handler);
    }

    @Test(expected = MockitoException.class)
    @SuppressWarnings("unchecked")
    public void testCreateMock_ThrowsException_WhenInstantiationExceptionOccurs() throws Exception {
        Class<Object> typeToMock = Object.class;
        Class<Object> proxyType = Object.class;

        when(settings.getSerializableMode()).thenReturn(SerializableMode.DEFAULT);
        when(settings.getTypeToMock()).thenReturn(typeToMock);
        when(cachingMockBytecodeGenerator.get(typeToMock, (Class[]) null)).thenReturn(proxyType);
        when(classInstantiator.instantiate(proxyType)).thenThrow(new org.mockito.internal.creation.instance.InstantiationException("failed"));

        mockMaker.createMock(settings, handler);
    }

    private <T> T any(Class<T> type) {
        return org.mockito.ArgumentMatchers.any(type);
    }
}
